def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find a full divider of color 2.
    divider = None
    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            divider = ('h', r)
            break
    if divider is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                divider = ('v', c)
                break
    if divider is None:
        return out

    bg = max(range(10), key=lambda k: sum(x == k for row in grid for x in row))
    axis, d = divider
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out

    if axis == 'v':
        # Slide the colored figure toward the divider until its bounding edge
        # is one cell away; draw an 8 stripe immediately behind it.
        if max(c for r, c in cells) < d:
            # Object lies left of divider: shift right until adjacent.
            shift = d - 1 - max(c for r, c in cells)
            newcells = [(r, c + shift) for r, c in cells]
            stripe = min(c for r, c in newcells) - 1
        else:
            # Object lies right of divider: shift left until adjacent.
            shift = d + 1 - min(c for r, c in cells)
            newcells = [(r, c + shift) for r, c in cells]
            stripe = max(c for r, c in newcells) + 1
        values = [grid[r][c] for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for (r, c), value in zip(newcells, values):
            out[r][c] = value
        if 0 <= stripe < w:
            for r in range(h):
                if out[r][stripe] == bg:
                    out[r][stripe] = 8
    else:
        if max(r for r, c in cells) < d:
            shift = d - 1 - max(r for r, c in cells)
            newcells = [(r + shift, c) for r, c in cells]
            stripe = min(r for r, c in newcells) - 1
        else:
            shift = d + 1 - min(r for r, c in cells)
            newcells = [(r + shift, c) for r, c in cells]
            stripe = max(r for r, c in newcells) + 1
        values = [grid[r][c] for r, c in cells]
        for r, c in cells:
            out[r][c] = bg
        for (r, c), value in zip(newcells, values):
            out[r][c] = value
        if 0 <= stripe < h:
            for c in range(w):
                if out[stripe][c] == bg:
                    out[stripe][c] = 8
    return out
